import { render, fireEvent, act, screen, waitFor } from '@testing-library/react'
import { TooltipController } from '../components/TooltipController'

export function advanceTimers(ms = 0) {
  act(() => {
    jest.advanceTimersByTime(ms)
  })
}

export function flushPendingTimers() {
  act(() => {
    jest.runOnlyPendingTimers()
  })
}

export async function flushMicrotasks() {
  await act(async () => {
    await Promise.resolve()
  })
}

export function fireWithTimers(callback, ms = 0) {
  act(() => {
    callback()
    if (ms) {
      jest.advanceTimersByTime(ms)
    }
  })
}

export function hoverAnchor(anchor, ms = 0) {
  fireWithTimers(() => {
    fireEvent.mouseEnter(anchor)
  }, ms)
}

export function unhoverAnchor(anchor, ms = 0) {
  fireWithTimers(() => {
    fireEvent.mouseLeave(anchor)
  }, ms)
}

export function clickAnchor(anchor, ms = 0) {
  fireWithTimers(() => {
    fireEvent.click(anchor)
  }, ms)
}

export async function waitForTooltip(id) {
  await waitFor(() => {
    expect(document.getElementById(id)).toBeInTheDocument()
  })
  return document.getElementById(id)
}

export async function waitForTooltipToClose(id) {
  await waitFor(() => {
    expect(document.getElementById(id)).not.toBeInTheDocument()
  })
}

export async function waitForTooltipToStopShowing(id) {
  await waitFor(() => {
    const tooltip = document.getElementById(id)
    expect(tooltip === null || tooltip.classList.contains('react-tooltip__closing')).toBe(true)
  })
}

export function renderTooltip({
  id = 'test-tooltip',
  anchorText = 'Hover Me',
  anchorProps = {},
  tooltipProps = {},
  anchor = <span data-tooltip-id={id}>{anchorText}</span>,
} = {}) {
  const view = render(
    <>
      {React.isValidElement(anchor)
        ? React.cloneElement(anchor, {
            'data-tooltip-id': anchor.props['data-tooltip-id'] ?? id,
            ...anchorProps,
          })
        : anchor}
      <TooltipController id={id} content={`${id} content`} {...tooltipProps} />
    </>,
  )

  const getAnchor = () =>
    anchorProps['aria-label']
      ? screen.getByLabelText(anchorProps['aria-label'])
      : screen.getByText(anchorText)

  return {
    ...view,
    id,
    getAnchor,
  }
}
/**
 * Shared document event delegation.
 *
 * Instead of N tooltips each calling document.addEventListener(type, handler),
 * we maintain ONE document listener per event type. When the event fires,
 * we iterate through all registered handlers for that type.
 *
 * This reduces document-level listeners from O(N × eventTypes) to O(eventTypes).
 */

type Handler = (event: Event) => void

const handlersByType = new Map<string, Set<Handler>>()

function getOrCreateSet(eventType: string): Set<Handler> {
  let set = handlersByType.get(eventType)
  if (!set) {
    set = new Set()
    handlersByType.set(eventType, set)
    document.addEventListener(eventType, dispatch)
  }
  return set
}

function dispatch(event: Event): void {
  const handlers = handlersByType.get(event.type)
  if (handlers) {
    // Safe to iterate directly — mutations (add/remove) only happen in
    // setup/cleanup, not during dispatch. Set iteration is stable for
    // entries that existed when iteration began.
    handlers.forEach((handler) => {
      handler(event)
    })
  }
}

/**
 * Register a handler for a document-level event type.
 * Returns an unsubscribe function.
 */
export function addDelegatedEventListener(eventType: string, handler: Handler): () => void {
  const set = getOrCreateSet(eventType)
  set.add(handler)

  return () => {
    set.delete(handler)
    if (set.size === 0) {
      handlersByType.delete(eventType)
      document.removeEventListener(eventType, dispatch)
    }
  }
}

/**
 * Reset for testing purposes.
 */
export function resetEventDelegation(): void {
  handlersByType.forEach((_handlers, eventType) => {
    document.removeEventListener(eventType, dispatch)
  })
  handlersByType.clear()
}
